'@|ConvertFrom-Json
$rows=foreach($d in $data){
 $r=$catalog.requirements|Where-Object id -eq $d.id
 if(-not $r){throw "Missing $($d.id)"}
 $fn=$r.obligations[0].checks[0].name
 $file=$d.file
 if($d.id -eq 'MB-0073'){$file='CodeQueryChecks.php:175'}
 [ordered]@{id=$d.id;criterion=$r.criterion;verdict=$d.verdict;rationale=$d.rationale;implementation_evidence=@("src/Engine/Checks/Families/$file",'src/Engine/Collectors/CodeInventoryCollector.php:31','docs/archive/automation-feasibility/source-probes.json');existing_function="$fn / $($d.method)";required_inputs=@($d.inputs);proposed_check=$d.predicate;tests=[ordered]@{safe=$d.safe;fail=$d.fail;missing='Missing/unreadable/oversized/malformed eligible inputs, truncated inventory or unresolved analysis must be UNKNOWN; no conversion to manual evidence and no PASS from zero files.'};effort=$d.effort;current_ready=$false;covered_by_active_ids=@($d.covered|Where-Object {$_});limitations=$d.limitations;sources=@($d.sources|Where-Object {$_})}
}
if(@($rows).Count -ne 23){throw 'Expected 23 rows'}
[IO.File]::WriteAllText("$PSScriptRoot/source.json", ($rows|ConvertTo-Json -Depth 12), [Text.UTF8Encoding]::new($false))
